    fn handle_tick_election(&mut self) {
        let now = C::now();

        tracing::debug!("try to trigger election, now: {}", now.display());

        if self.engine.state.server_state == ServerState::Leader {
            let transfer_expired = self.engine.leader_ref().is_some_and(|leader| leader.is_transfer_expired());
            if !transfer_expired {
                tracing::debug!("skip election, already a leader");
                return;
            }
            tracing::info!("leadership transfer has not completed in time, start an election");
        }

        if !self.engine.state.membership_state.is_campaigner_in_effective_or_committed(&self.id) {
            tracing::debug!("skip election, not a campaigner in effective or committed membership");
            return;
        }

        if !self.runtime_config.enable_elect.load(Ordering::Relaxed) {
            tracing::debug!("skip election, election disabled");
            return;
        }

        let mut election_timeout = self.engine.config.timer_config.election_timeout;
        if self.engine.is_there_greater_log() {
            election_timeout += self.engine.config.timer_config.smaller_log_timeout;
        }

        let effective = self.engine.state.membership_state.effective();
        // A sole voter may elect immediately only while holding its own vote. It must honor a
        // vote granted to a campaigner outside the voter sets.
        let is_sole_voter = effective.voter_ids().eq([self.id.clone()]);
        let vote = self.engine.state.vote_ref();
        let votes_for_self = vote.leader_node_id() == &self.id;
        let may_campaign = effective.is_campaigner(&self.id);
        let is_single_campaigner = may_campaign && is_sole_voter && votes_for_self;

        if is_single_campaigner {
            // When a node restart, it may stay in any state but the in progress election(engine.candidate) is
            // empty.
            if self.engine.candidate_ref().is_some() {
                tracing::debug!("skip election, single voter already has an active election in progress");
                return;
            }
            tracing::debug!("single voter, elect immediately");
        } else {
            tracing::debug!("check election timeout");

            let local_vote = &self.engine.state.vote;
            tracing::debug!("local vote: {}, election_timeout: {:?}", local_vote, election_timeout,);

            if local_vote.is_expired(now, election_timeout) {
                tracing::info!("election timeout expired, triggering election");
            } else {
                tracing::debug!("election timeout not yet expired");
                return;
            }
        }

        // Only the sole effective voter holding its own vote can skip Pre-Vote. A removed
        // committed voter still needs a remote quorum, even if there is only one effective voter.
        let pre_vote = self.runtime_config.enable_pre_vote.load(Ordering::Relaxed) && !is_single_campaigner;

use std::time::Duration;

use openraft::Config;
use openraft::ServerState;
use openraft::metrics::WaitError;

use crate::fixtures::Node;
use crate::fixtures::RaftRouter;
use crate::fixtures::timeout;
use crate::fixtures::ut_harness;

/// `wait_for_recovery` returns once the cluster commit is re-established and the state machine has
/// applied up to it.
///
/// A follower restarts with a cleared (transient) state machine and `save_committed` disabled, so
/// nothing is recovered locally on startup — recovery is driven entirely by the cluster commit the
/// leader replicates. The surviving `{0,2}` quorum keeps that commit established.
#[tracing::instrument]
#[test_harness::test(harness = ut_harness)]
async fn wait_for_recovery_recovers_state_machine() -> anyhow::Result<()> {
    let config = Config {
        enable_heartbeat: true,
        enable_elect: false,
        ..Default::default()
    };

    let mut router = RaftRouter::new(config)?;
    // Recovery must come from the cluster commit, not a locally restored committed pointer.
    router.enable_saving_committed = false;

    tracing::info!("--- bring up a 3-node cluster; node-0 is the leader");
    let log_index = router.new_cluster([0, 1, 2], []).await?;

    tracing::info!(log_index, "--- restart follower node-1 with a cleared state machine");
    {
        let Node {
            log_store: ls,
            state_machine: sm,
            ..
        } = router.stop_node(1).await?;

        // Transient state machine: in-memory applied state is lost on restart.
        sm.clear_state_machine().await;

        router.new_raft_node_with_sto(1, ls, sm).await?;
    }

    tracing::info!(
        log_index,
        "--- wait_for_recovery returns once the state machine catches up"
    );
    {
        let m = router.get_raft_handle(&1)?.wait_for_recovery(timeout()).await?;

        assert!(m.cluster_committed.is_some(), "the cluster commit is perceived");
        assert!(
            m.last_applied.as_ref().map(|x| x.index()) >= Some(log_index),
            "state machine recovered: last_applied {:?} >= {}",
            m.last_applied,
            log_index
        );
    }

    Ok(())
}

/// `wait_for_recovery` times out when no cluster commit can be re-established.
///
/// A restarted leader that has lost its quorum never perceives a non-null cluster commit, so the
/// recovery wait cannot complete and returns [`WaitError::Timeout`].
#[tracing::instrument]
#[test_harness::test(harness = ut_harness)]
async fn wait_for_recovery_times_out_without_quorum() -> anyhow::Result<()> {
    let config = Config {
        enable_heartbeat: false,
        enable_elect: false,
        ..Default::default()
    };

    let mut router = RaftRouter::new(config)?;

    tracing::info!("--- bring up a 3-node cluster; node-0 is the leader");
    let _log_index = router.new_cluster([0, 1, 2], []).await?;

    tracing::info!("--- take both followers offline so the leader loses its quorum");
    for id in [1, 2] {
        router.stop_node(id).await?;
    }

    tracing::info!("--- restart node-0; it restores leadership but cannot re-establish the commit");
    {
        let Node {
            log_store: ls,
            state_machine: sm,
            ..
        } = router.stop_node(0).await?;

        router.new_raft_node_with_sto(0, ls, sm).await?;
        router.wait(&0).state(ServerState::Leader, "restore leadership without election").await?;
    }

    tracing::info!("--- with no quorum the cluster commit stays null, so recovery times out");
    {
        let res = router.get_raft_handle(&0)?.wait_for_recovery(Some(Duration::from_millis(500))).await;
        assert!(
            matches!(res, Err(WaitError::Timeout(..))),
            "expected a timeout, got {:?}",
            res
        );
    }

    Ok(())
}
